SELECT jsonb_build_object('schema_version','ml-snapshot-v1','organization_id',$1::uuid,'source','server_simulator','captured_at',clock_timestamp(),'stations',(SELECT jsonb_agg(jsonb_build_object('id',id,'created_at',created_at,'archived_at',archived_at,'snapshot_limit_kw',limit_kw) ORDER BY id) FROM stations WHERE organization_id=$1::uuid),'hours',(SELECT jsonb_agg(jsonb_build_object('station_id',station_id,'start',interval_start,'end',interval_end,'quality',quality,'average_kw',average_power_w/1000,'subset_kw',measured_subset_average_w/1000,'built_at',built_at,'gap_count',gap_count,'boundary_count',boundary_count,'observed_ms',observed_ms,'expected_session_ms',expected_session_ms,'covered_session_ms',covered_session_ms,'sample_count',sample_count,'local_limit_kw',local_limit_kw,'rule',rule) ORDER BY interval_start,station_id) FROM power_measurements WHERE organization_id=$1::uuid),'grid',(SELECT jsonb_agg(jsonb_build_object('received_at',received_at,'created_at',created_at,'budget_w',budget_w,'validity',validity,'freshness_seconds',freshness_seconds) ORDER BY id) FROM grid_samples WHERE organization_id=$1::uuid)) AS snapshot
